import { create } from 'zustand'

type BearState = {
  bears: number
  increment: () => void
}

const createSelectors = <S extends { getState: () => object; (selector: (state: any) => any): any }>(store: S) => {
  const typedStore = store as S & { use: { [K in keyof ReturnType<S['getState']>]: () => ReturnType<S['getState']>[K] } }
  typedStore.use = {} as typeof typedStore.use
  for (const key of Object.keys(store.getState())) {
    ;(typedStore.use as any)[key] = () => store((state: any) => state[key])
  }
  return typedStore
}

const useBearStore = create<BearState>((set) => ({
  bears: 0,
  increment: () => set((state) => ({ bears: state.bears + 1 })),
}))

