import { createContext, useContext, useState, type ReactNode } from 'react'
import { createStore, useStore } from 'zustand'

type CounterState = { count: number; increment: () => void }
const createCounterStore = () => createStore<CounterState>((set) => ({
  count: 0,
  increment: () => set((state) => ({ count: state.count + 1 })),
}))

const CounterContext = createContext<ReturnType<typeof createCounterStore> | null>(null)
function CounterProvider({ children }: { children: ReactNode }) {
  const [store] = useState(createCounterStore)
  return <CounterContext.Provider value={store}>{children}</CounterContext.Provider>
}
function useCounter<T>(selector: (state: CounterState) => T) {
  const store = useContext(CounterContext)
  if (!store) throw new Error('Missing CounterProvider')
  return useStore(store, selector)
}
function Counter() {
  const count = useCounter((state) => state.count)
  const increment = useCounter((state) => state.increment)
  return <button onClick={increment}>{count}</button>
}
export function App() {
  return <CounterProvider><Counter /></CounterProvider>
}

